// NetworkModule — 声明 .high，确保网络监听最先就绪
class NetworkModule: AppModule {
    var priority: ModulePriority { .high }

    func register(context: AppContext) {
        ServiceRegistry.shared.register(
            NetworkMonitorProviding.self,
            instance: NetworkMonitor.shared
        )
    }

    func initialize(context: AppContext) {
        NetworkMonitor.shared.startMonitoring()
    }
}
```
